head.script:
scwin.gVar = {
    "cMinlength" : "",
    "cValue" : "",
    "cLengthLimit" : "",
    "cMinByteLength" : "",
    "cDisplaymessage" : "",
    "cInvalidMessage" : "",
    "cInvalidMessageFunc" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > minlength]<br/>Secret 컴포넌트에 입력하는 값의 최소 길이를 설정합니다.",
    "validation" : [
        "입력값 유효성 체크 시 사용되는 속성이며 validate() 메소드로 유효성 체크를 수행합니다.",
        "한 문자의 길이를 1 로 계산(다국어 포함)하여 입력값의 최소 길이를 숫자로 설정합니다.",
        "값을 설정하지 않으면 최소 길이에 대한 유효성 체크를 수행하지 않습니다.",
        "입력값이 없거나 입력값의 길이가 설정값보다 작으면 유효성 체크는 실패로 처리되고 displaymessage 속성에 따라 실패 메시지가 출력됩니다.",
        "시스템 기본 메시지는 'n자 이상 입력해야 합니다.' 이며, invalidMessage 또는 invalidMessageFunc 속성으로 메시지를 변경할 수 있습니다.",
        "maxBytelength 또는 maxlength 속성을 minlength 값보다 작게 설정한 경우 유효성 체크는 항상 실패로 처리됩니다.",
        "minByteLength 를 함께 설정한 경우 minlength 의 유효성 체크가 먼저 실행됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 은 코드값, 자체 값 selectbox 는 value)
    con_minlength.setValue("10");
    con_value.setValue("secret");
    con_lengthLimit.setSelectedIndex(0);
    con_minByteLength.setSelectedIndex(0);
    con_displaymessage.setValue("2");
    con_invalidMessageFunc.setValue("1");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="입력값 선택지의 길이/Byte 는 빈값 / secret (6자 6byte) / 가나다라마바 (6자 12byte) / 가나다라마바사아자차 (10자 20byte) 입니다\npassword 라 화면으로 글자 수를 셀 수 없으므로, 결과창의 값 길이와 alert 문구(어느 속성의 메시지인지)로 판정합니다"', '', 'label1');

    // 조건 설정
    scwin.gVar["cMinlength"] = con_minlength.getValue();
    scwin.gVar["cValue"] = con_value.getValue();
    scwin.gVar["cLengthLimit"] = con_lengthLimit.getValue();
    scwin.gVar["cMinByteLength"] = con_minByteLength.getValue();
    scwin.gVar["cDisplaymessage"] = con_displaymessage.getText();
    scwin.gVar["cInvalidMessage"] = con_invalidMessage.getValue();
    scwin.gVar["cInvalidMessageFunc"] = con_invalidMessageFunc.getText();

    let properties = {
        minlength : scwin.gVar["cMinlength"],
        minByteLength : scwin.gVar["cMinByteLength"],
        displaymessage : scwin.gVar["cDisplaymessage"],
        invalidMessage : scwin.gVar["cInvalidMessage"],
        invalidMessageFunc : scwin.gVar["cInvalidMessageFunc"],
    }

    // minlength 보다 작은 길이 제한 속성 (선택한 1개만 적용)
    if (scwin.gVar["cLengthLimit"] === "maxlength")
        properties.maxlength = "3";
    else if (scwin.gVar["cLengthLimit"] === "maxByteLength")
        properties.maxByteLength = "3";

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출
    await $c.gcm.createBasicSecret(cList);

    // 헬퍼가 넣은 초기값 secret 을 입력값 조건에 맞춰 덮음 (빈값 케이스 재현)
    if (scwin.gVar["cValue"] === "empty")
        target1.setValue("");
    else
        target1.setValue(scwin.gVar["cValue"]);
}



// validate 실행 (minlength 발동 수단) - validation 1 ~ 7 판정 출력
scwin.btn_validate_onclick = function (e) {
    // password 는 화면으로 글자 수 확인이 불가하므로 판정 근거로 값 길이를 함께 출력
    let nLength = (target1.getValue() || "").length;
    let rtn = target1.validate();

    let strMinlength = (scwin.gVar["cMinlength"] === "") ? "미설정" : scwin.gVar["cMinlength"];
    let strLengthLimit = (scwin.gVar["cLengthLimit"] === "") ? "미설정" : scwin.gVar["cLengthLimit"] + "=3";
    let strMinByteLength = (scwin.gVar["cMinByteLength"] === "") ? "미설정" : scwin.gVar["cMinByteLength"];
    let strDisplaymessage = (scwin.gVar["cDisplaymessage"] === "") ? "미설정" : scwin.gVar["cDisplaymessage"];
    let strInvalidMessage = (scwin.gVar["cInvalidMessage"] === "") ? "미설정" : scwin.gVar["cInvalidMessage"];
    let strInvalidMessageFunc = (scwin.gVar["cInvalidMessageFunc"] === "") ? "미설정" : scwin.gVar["cInvalidMessageFunc"];

    wf_body_bottom.getObj("scwin").setReturnValue("minlength " + strMinlength + " / target1 값 길이 " + nLength + " / 길이 제한 속성 " + strLengthLimit + " / minByteLength " + strMinByteLength + " / displaymessage " + strDisplaymessage + " / invalidMessage " + strInvalidMessage + " / invalidMessageFunc " + strInvalidMessageFunc + " -> validate() 반환값 : " + rtn);
}



// invalidMessageFunc 로 설정되는 사용자 정의 메시지 함수
scwin.fn_msg = function () {
    return "invalidMessageFunc 메시지 (원인 : " + this.getType() + ")";
}
